<?php $page_title='Analytics'; require 'layout.php';
$tot=$pdo->query("SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM food_donations) donations,(SELECT COUNT(*) FROM food_donations WHERE status='completed') completed,(SELECT COALESCE(SUM(quantity),0) FROM food_donations) quantity,(SELECT COUNT(*) FROM ngos) ngos,(SELECT COUNT(*) FROM volunteers) volunteers,(SELECT COUNT(*) FROM campaigns) campaigns,(SELECT COUNT(*) FROM deliveries WHERE status='delivered') deliveries")->fetch();
$months=$pdo->query("SELECT DATE_FORMAT(created_at,'%b %Y') label,COUNT(*) total FROM food_donations GROUP BY YEAR(created_at),MONTH(created_at) ORDER BY YEAR(created_at),MONTH(created_at) DESC LIMIT 6")->fetchAll();
$cats=$pdo->query("SELECT category,COUNT(*) total FROM food_donations GROUP BY category ORDER BY total DESC LIMIT 8")->fetchAll();
?><section class="admin-page-head"><div><span class="kicker">ADMIN / ANALYTICS</span><h1>Impact Analytics</h1><p>Real database-driven platform health and donation metrics.</p></div></section><div class="analytics-kpis"><div><span>Users</span><b><?=intval($tot['users'])?></b></div><div><span>Donations</span><b><?=intval($tot['donations'])?></b></div><div><span>Completed</span><b><?=intval($tot['completed'])?></b></div><div><span>Meals / units</span><b><?=intval($tot['quantity'])?></b></div><div><span>NGOs</span><b><?=intval($tot['ngos'])?></b></div><div><span>Volunteers</span><b><?=intval($tot['volunteers'])?></b></div><div><span>Campaigns</span><b><?=intval($tot['campaigns'])?></b></div><div><span>Delivered</span><b><?=intval($tot['deliveries'])?></b></div></div><div class="analytics-grid"><section class="admin-table-card"><h2>Monthly donations</h2><?php foreach($months as $m):?><div class="bar-row"><span><?=e($m['label'])?></span><div><i style="width:<?=min(100,max(5,$m['total']*10))?>%"></i></div><b><?=intval($m['total'])?></b></div><?php endforeach;if(!$months):?><p class="muted">Donation data will appear here as users contribute food.</p><?php endif;?></section><section class="admin-table-card"><h2>Food categories</h2><?php foreach($cats as $c):?><div class="bar-row"><span><?=e($c['category'])?></span><div><i style="width:<?=min(100,max(5,$c['total']*10))?>%"></i></div><b><?=intval($c['total'])?></b></div><?php endforeach;?></section></div><?php require 'footer.php'; ?>
